// Security & Reliability Ingress Guardrail
// 1. Drop Slack Retries to prevent runaway execution loops
// 2. Validate Event Integrity
const headers = $json.headers || {};
const body = $json.body || {};

const isRetry = headers['x-slack-retry-num'] !== undefined || headers['X-Slack-Retry-Num'] !== undefined;
const event = body.event || {};
const isBot = event.bot_id !== undefined || event.subtype === 'bot_message';
const isValidEvent = (event.type === 'app_mention' || event.type === 'message') && !isBot;

return [{
  json: {
    is_retry: isRetry,
    is_valid_event: isValidEvent,
    event: event,
    channel_id: event.channel,
    thread_ts: event.thread_ts || event.ts,
    user_id: event.user,
    prompt_text: (event.text || '').replace(/<@[A-Z0-9]+>/g, '').trim(),
    files: event.files || []
  }
}];

