// Dynamic Multi-Client Brain Engine
// Identifies client by channel ID, prompt keywords, or default
const prompt = $('Security & Retry Guardrail').item.json.prompt_text.toLowerCase();
const channelId = $('Security & Retry Guardrail').item.json.channel_id;
const files = $('Security & Retry Guardrail').item.json.files || [];

let clientId = 'apex_athletics';
if (prompt.includes('maria b') || prompt.includes('lawn') || prompt.includes('couture') || prompt.includes('bridal')) {
  clientId = 'maria_b';
}

// Brand Brain Definitions
const brandBrains = {
  apex_athletics: {
    client_id: 'apex_athletics',
    company_name: 'Apex Athletics Global',
    industry: 'High-Performance Biomechanical Sportswear',
    colors: 'Primary Dark #0B0C10, Accent Cyan #66FCF1, Secondary #45A29E, Pure White #FFFFFF',
    typography: 'Futura Bold / ALL CAPS / Max 4 words in graphic',
    tone: 'Empowering, Direct, High-Performance, Minimalist',
    banned_elements: 'No cheap yellow discount badges, no smiling stock models, no distorted anatomy',
    golden_examples: 'Moody trail runner silhouette with cyan bold text DEFIANCE; Macro fiber weave shot with white text UNBREAKABLE',
    rejections: 'Rejected bright yellow discount badge; Rejected deformed hand with 6 fingers',
    fashion_rule: null
  },
  maria_b: {
    client_id: 'maria_b',
    company_name: 'Maria B Designs',
    industry: 'Luxury Haute Couture, Embroidered Lawn & Bridal Wear',
    colors: 'Primary Plum #4A0E2E, Accent Gold #D4AF37, Secondary Rose #C59B9B, Ivory #FDFBF7',
    typography: 'Playfair Display / Bodoni Bold Serif / Elegant Title Case',
    tone: 'Regal, Poetic, Artisanal, Graceful, Sophisticated',
    banned_elements: 'No cartoonish styles, no neon colors, no cheap sales badges, NEVER alter authentic garment embroidery',
    golden_examples: 'Sunlit Lahore fort courtyard with authentic embroidered chiffon suit and gold serif text Noor-e-Jahan',
    rejections: 'Rejected synthetic AI embroidery that mismatched actual retail catalog suit',
    fashion_rule: 'CRITICAL PRODUCT INTEGRITY: Never synthesize or alter garments. Accept authentic product attachments from Slack. The image engine generates only heritage architectural backgrounds, atmospheric lighting, and regal typography around the real garment.'
