// Parse Slack Block Kit URL-encoded interactive payload
let payload = $json.body;
if (typeof payload === 'string') {
  payload = JSON.parse(decodeURIComponent(payload.replace(/^payload=/, '')));
} else if (payload.payload) {
  payload = typeof payload.payload === 'string' ? JSON.parse(payload.payload) : payload.payload;
}

const action = (payload.actions && payload.actions[0]) || {};
const actionId = action.action_id || 'unknown';
const actionValue = action.value || '';
const parts = actionValue.split(':');
const campaignId = parts[0] || 'unknown';
const currentPost = parseInt(parts[1] || '1', 10);

return [{
  json: {
    action_id: actionId,
    campaign_id: campaignId,
    current_post: currentPost,
    channel_id: payload.channel ? payload.channel.id : '',
    thread_ts: payload.message ? payload.message.ts : '',
    user_id: payload.user ? payload.user.id : '',
    response_url: payload.response_url
  }
}];
